846	
847	    if (!disk->supportZeroCopyReplication() || !disk->checkUniqueId(part_id))
848	    {
849	        throw Exception(ErrorCodes::ZERO_COPY_REPLICATION_ERROR, "Part {} unique id {} doesn't exist on {}.", part_name, part_id, disk->getName());
850	    }
851	
852	    LOG_DEBUG(log, "Downloading Part {} unique id {} metadata onto disk {}.",
853	        part_name, part_id, disk->getName());
854	
855	    data.lockSharedDataTemporary(part_name, part_id, disk);
856	
857	    static const String TMP_PREFIX = "tmp-fetch_";
858	    String tmp_prefix = tmp_prefix_.empty() ? TMP_PREFIX : tmp_prefix_;
859	
860	    String part_dir = tmp_prefix + part_name;
861	    String part_relative_path = data.getRelativeDataPath() + String(to_detached ? "detached/" : "");
862	
863	    auto volume = std::make_shared<SingleDiskVolume>("volume_" + part_name, disk);
864	
865	    auto data_part_storage = std::make_shared<DataPartStorageOnDisk>(
866	        volume,
