875	    if (data_part_storage->exists())
876	        throw Exception(ErrorCodes::DIRECTORY_ALREADY_EXISTS, "Directory {} already exists.", data_part_storage->getFullPath());
877	
878	    CurrentMetrics::Increment metric_increment{CurrentMetrics::ReplicatedFetch};
879	
880	    volume->getDisk()->createDirectories(data_part_storage->getFullPath());
881	
882	    size_t files;
883	    readBinary(files, in);
884	
885	    for (size_t i = 0; i < files; ++i)
886	    {
887	        String file_name;
888	        UInt64 file_size;
889	
890	        readStringBinary(file_name, in);
891	        readBinary(file_size, in);
892	
893	        String metadata_file = fs::path(data_part_storage->getFullPath()) / file_name;
894	
895	        {
896	            auto file_out = std::make_unique<WriteBufferFromFile>(metadata_file, DBMS_DEFAULT_BUFFER_SIZE, -1, 0666, nullptr, 0);
897	
