230	{
231	    auto metadata_snapshot = data.getInMemoryMetadataPtr();
232	    for (const auto & [name, projection] : projections)
233	    {
234	        auto projection_sample_block = metadata_snapshot->projections.get(name).sample_block;
235	        auto part_in_memory = asInMemoryPart(projection);
236	        if (!part_in_memory)
237	            throw Exception(ErrorCodes::LOGICAL_ERROR, "Projection {} of part {} is not stored in memory", name, part->name);
238	
239	        writeStringBinary(name, out);
240	        projection->checksums.write(out);
241	        NativeWriter block_out(out, 0, projection_sample_block);
242	        block_out.write(part_in_memory->block);
243	    }
244	
245	    auto part_in_memory = asInMemoryPart(part);
246	    if (!part_in_memory)
247	        throw Exception(ErrorCodes::LOGICAL_ERROR, "Part {} is not stored in memory", part->name);
248	
249	    NativeWriter block_out(out, 0, metadata_snapshot->getSampleBlock());
250	    part->checksums.write(out);
251	    block_out.write(part_in_memory->block);
252	
253	    data.getSendsThrottler()->add(part_in_memory->block.bytes());
